public class ResourcePrefixDetector extends Detector
        implements XmlScanner, ResourceFolderScanner {
    private static final String ATTR_RESOURCE_PREFIX = "resourcePrefix";
    private String mResourcePrefix;

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mResourcePrefix = null;
    }

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        mResourcePrefix = context.getProject().getResourcePrefix();
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (mResourcePrefix == null) return;
        String name = element.getAttribute("name");
        if (name.isEmpty()) return;
        if (!name.startsWith(mResourcePrefix)) {
            context.report(ISSUE, element, context.getLocation(element), 
                "Resource named '" + name + "' does not start with resource prefix '" + mResourcePrefix + "'");
        }
    }

    @Override
    public void checkFolder(@NonNull ResourceContext context, @NonNull ResourceFolderType folderType, @NonNull File folder) {
        if (mResourcePrefix == null) return;
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            String fileName = file.getName();
            String resourceName = getBaseName(fileName);
            if (resourceName.isEmpty()) continue;
            if (!resourceName.startsWith(mResourcePrefix)) {
                context.report(ISSUE, file, context.getLocation(file), ...);
            }
        }
    }

    private static String getBaseName(String fileName) {
        int dot = fileName.indexOf('.');
        return dot == -1 ? fileName : fileName.substring(0, dot);
    }
}
```
