package com.android.tools.lint.checks;

import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.ResourceContext;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.io.File;
import java.util.Collection;
import java.util.EnumSet;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class ResourcePrefixDetector extends Detector implements XmlScanner, ResourceFolderScanner {

    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "In Gradle projects you can specify a resource prefix that all resources in the project must conform to. "
                    + "Resources that do not start with the configured prefix can accidentally conflict with resources from other libraries.",
            Category.CORRECTNESS,
            3,
            Severity.WARNING,
            new Implementation(
                    ResourcePrefixDetector.class,
                    EnumSet.of(Scope.RESOURCE_FILE_SCOPE, Scope.RESOURCE_FOLDER_SCOPE)));

    private static final String ATTR_NAME = "name";
    private String mResourcePrefix;

    @Override
    public void beforeCheckRootProject(@NonNull Context context) {
        mResourcePrefix = null;
    }

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        mResourcePrefix = context.getProject().getResourcePrefix();
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (mResourcePrefix == null || mResourcePrefix.isEmpty()) {
            return;
        }
        if (!element.hasAttribute(ATTR_NAME)) {
            return;
        }
        String name = element.getAttribute(ATTR_NAME);
        if (name.isEmpty()) {
            return;
        }
        if (!name.startsWith(mResourcePrefix)) {
            Attr attr = element.getAttributeNode(ATTR_NAME);
            Location location = attr != null ? context.getLocation(attr) : context.getLocation(element);
            context.report(
                    ISSUE,
                    attr != null ? context.getLocation(attr) : context.getLocation(element),
                    location,
                    String.format(
                            "Resource name `%1$s` does not start with the configured resource prefix `%2$s`",
                            name,
                            mResourcePrefix));
        }
    }

    @Override
    public void checkFolder(
            @NonNull ResourceContext context,
            @NonNull ResourceFolderType folderType,
            @NonNull File folder) {
        if (mResourcePrefix == null || mResourcePrefix.isEmpty()) {
            return;
        }
        if (folderType == ResourceFolderType.VALUES) {
            return;
        }
        File[] files = folder.listFiles();
        if (files == null) {
            return;
        }
        for (File file : files) {
            if (file.isDirectory()) {
                continue;
            }
            String resourceName = getResourceName(file.getName());
            if (resourceName.isEmpty()) {
                continue;
            }
            if (!resourceName.startsWith(mResourcePrefix)) {
                context.report(
                        ISSUE,
                        file,
                        context.getLocation(file),
                        String.format(
                                "Resource name `%1$s` does not start with the configured resource prefix `%2$s`",
                                resourceName,
                                mResourcePrefix));
            }
        }
    }

    private static String getResourceName(String fileName) {
        if (fileName.endsWith(".9.png")) {
            return fileName.substring(0, fileName.length() - ".9.png".length());
        }
        int dot = fileName.lastIndexOf('.');
        return dot > 0 ? fileName.substring(0, dot) : fileName;
    }
}
```

